/* Static controls matching the observed Element Plus UI. No remote actions. */
'use strict';
window.AdminControls=(()=>{
let active=null,serial=0;
const make=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e;};
function popup(trigger,panel){
 panel.classList.add('live-popover');panel.id='live-options-'+(++serial);panel.setAttribute('popover','manual');trigger.setAttribute('aria-controls',panel.id);trigger.setAttribute('aria-expanded','false');
 const close=()=>{if(panel.matches(':popover-open'))panel.hidePopover();trigger.setAttribute('aria-expanded','false');if(active?.panel===panel)active=null;};
 const position=()=>{const r=trigger.getBoundingClientRect(),height=Math.min(panel.scrollHeight,280),room=innerHeight-r.bottom-12;panel.style.width=Math.min(Math.max(r.width,200),innerWidth-24)+'px';panel.style.left=Math.max(12,Math.min(r.left,innerWidth-parseFloat(panel.style.width)-12))+'px';panel.style.maxHeight=Math.max(100,Math.min(280,Math.max(room,r.top-12)))+'px';panel.style.top=(room>=height?r.bottom+8:Math.max(8,r.top-height-8))+'px';};
 const open=()=>{if(active?.panel!==panel)active?.close();if(!panel.matches(':popover-open'))panel.showPopover();position();trigger.setAttribute('aria-expanded','true');active={panel,trigger,close,position};panel.querySelector('input[type=search]')?.focus();};
 trigger.addEventListener('click',e=>{e.preventDefault();panel.matches(':popover-open')?close():open();});
 trigger.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();open();panel.querySelector('button:not(:disabled),input[type=checkbox]:not(:disabled)')?.focus();}});
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();trigger.focus();}if(['ArrowDown','ArrowUp'].includes(e.key)){const choices=[...panel.querySelectorAll('button:not(:disabled),input[type=checkbox]:not(:disabled)')].filter(n=>n.offsetHeight&&!n.closest('[hidden]'));if(choices.length){e.preventDefault();const i=choices.indexOf(document.activeElement);choices[(i+(e.key==='ArrowDown'?1:-1)+choices.length)%choices.length].focus();}}if(e.key==='Tab'){close();}});
 return {open,close,position};
}
function select(select,label){
 if(select.closest('.live-select'))return select.parentElement;
 const box=make('div','live-select'),trigger=make('button','live-select-trigger'),caption=make('span','live-select-caption'),arrow=make('span','live-select-arrow'),clear=make('button','live-select-clear','×'),panel=make('div','live-options'),search=make('input','live-select-search'),list=make('div','live-option-list');
 trigger.type=clear.type='button';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',label||select.getAttribute('aria-label')||'选择');trigger.setAttribute('aria-haspopup','listbox');clear.setAttribute('aria-label','清空'+label);list.setAttribute('role','listbox');search.type='search';search.placeholder='请输入关键词';search.setAttribute('aria-label','搜索'+label+'选项');trigger.append(caption,arrow);panel.append(search,list);box.append(select,trigger,clear,panel);select.classList.add('live-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const pop=popup(trigger,panel);
 function draw(){const options=[...select.options];search.hidden=options.length<20;caption.textContent=select.selectedOptions[0]?.text||'请选择';trigger.classList.toggle('is-placeholder',!select.value);trigger.disabled=select.disabled;clear.hidden=!select.value||select.required||select.disabled||!options.some(o=>!o.value);list.replaceChildren();let count=0;for(const o of options){if(search.value&&!o.text.toLowerCase().includes(search.value.toLowerCase()))continue;const b=make('button','live-option'+(o.selected?' selected':''),o.text);b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected',String(o.selected));b.disabled=o.disabled;b.onclick=()=>{select.value=o.value;select.dispatchEvent(new Event('change',{bubbles:true}));trigger.removeAttribute('aria-invalid');draw();pop.close();trigger.focus();};list.append(b);count++;}if(!count)list.append(make('div','live-no-options','无匹配数据'));}
 clear.onclick=e=>{e.preventDefault();select.value='';select.dispatchEvent(new Event('change',{bubbles:true}));draw();trigger.focus();};search.oninput=draw;select.addEventListener('change',draw);select.addEventListener('invalid',e=>{e.preventDefault();trigger.setAttribute('aria-invalid','true');pop.open();});new MutationObserver(draw).observe(select,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','selected']});draw();return box;
}
function multi(box){if(box.dataset.enhanced)return;box.dataset.enhanced='true';const summary=box.querySelector('.multi-summary'),search=box.querySelector('input[type=search]'),list=box.querySelector('.multi-options');if(!summary||!search||!list)return;const label=box.dataset.field||'选项',trigger=make('button','live-select-trigger multi-trigger'),panel=make('div','live-options'),clear=make('button','live-select-clear','×');trigger.type=clear.type='button';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',label);trigger.setAttribute('aria-haspopup','listbox');clear.setAttribute('aria-label','清空'+label);summary.remove();search.classList.add('live-select-search');panel.append(search,list);box.append(trigger,clear,panel);list.setAttribute('role','listbox');list.setAttribute('aria-multiselectable','true');const pop=popup(trigger,panel);
 const draw=()=>{const values=[...list.querySelectorAll('input:checked')].map(i=>i.value);trigger.replaceChildren();trigger.classList.toggle('is-placeholder',!values.length);if(!values.length)trigger.append(make('span','live-select-caption','请选择'+label));else{values.slice(0,2).forEach(v=>trigger.append(make('span','live-selected-chip',v)));if(values.length>2)trigger.append(make('span','live-selected-chip','+'+(values.length-2)));}trigger.append(make('span','live-select-arrow'));clear.hidden=!values.length;list.querySelectorAll('label').forEach(l=>{const i=l.querySelector('input');l.setAttribute('role','option');l.setAttribute('aria-selected',String(i.checked));l.classList.toggle('selected',i.checked);l.classList.toggle('disabled',i.disabled);});};
 list.addEventListener('change',draw);clear.onclick=e=>{e.preventDefault();list.querySelectorAll('input:checked').forEach(i=>{if(!i.disabled)i.checked=false;});draw();};draw();return box;
}
function enhance(){document.querySelectorAll('select:not(.live-native)').forEach(s=>{if(s.multiple)return;const label=s.closest('.field')?.querySelector(':scope>span')?.textContent||s.getAttribute('aria-label')||'选项';const old=s.parentElement;if(old.classList.contains('searchable-select')){old.replaceWith(select(s,label));}else{const marker=document.createTextNode('');s.before(marker);marker.replaceWith(select(s,label));}});document.querySelectorAll('.multi-picker:not([data-enhanced])').forEach(multi);}
 document.addEventListener('pointerdown',e=>{if(active&&!active.panel.contains(e.target)&&!active.trigger.contains(e.target))active.close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();e.stopImmediatePropagation();const t=active.trigger;active.close();t.focus();}},true);window.addEventListener('resize',()=>active?.position());document.addEventListener('scroll',()=>active?.position(),true);
 new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});
 return {select,multi,enhance,close:()=>active?.close()};
})();
